#!/usr/bin/env python3

def analyze_lines(filename):
    with open(filename, 'r') as f:
        lines = f.readlines()

    print(f"Total lines: {len(lines)}")

    # Check if any lines have exactly 26 unique characters (potential alphabets)
    for i, line in enumerate(lines):
        clean_line = ''.join(c.lower() for c in line if c.isalpha())
        unique_chars = set(clean_line)
        print(f"Line {i+1}: {len(unique_chars)} unique characters")
        if len(unique_chars) == 26:
            print(f"  *** Potential alphabet at line {i+1}: {''.join(sorted(unique_chars))}")

    # Check first few characters of each line
    print("\nFirst 5 characters of each line:")
    for i, line in enumerate(lines):
        clean_line = ''.join(c.lower() for c in line if c.isalpha())
        print(f"Line {i+1}: {clean_line[:5]}")

    # Look for lines with interesting patterns or keywords
    keywords = ["fibonacci", "fib", "key", "cipher", "alphabet", "sequence"]
    for i, line in enumerate(lines):
        for keyword in keywords:
            if keyword in line.lower():
                print(f"Line {i+1} contains '{keyword}': {line.strip()}")

if __name__ == "__main__":
    analyze_lines("/home/ctfplayer/ctf_files/ramblings")
